"""IDE workshops. Completion is evidence for review, never automatic certification."""


def lab(number, module, title, hours, goal, theory, example, steps, criteria, transfer):
    return dict(id=f'{number:02}-lab', module=module, title=title, minutes=hours * 60,
                kind='lab', goal=goal, theory=theory, example=example,
                breakdown=steps, tip=transfer, task='Выполни шаги в IDE. Запиши доказательства в отчёт ниже.',
                starter='Репозиторий / файлы:\nКоманда запуска и результат:\nНайденная ошибка и её причина:\nКритерии приёмки и доказательства:\nЧто сделал с ИИ и как проверил:\nПовторное решение без подсказки:\n',
                hints=['Сначала воспроизведи минимальный пример. Затем меняй одно условие за раз.',
                       'Если застрял, приложи минимальный код, ожидаемое поведение и полный текст ошибки.'],
                criteria=criteria, checks='')


